import { EmitterConfig, OldEmitterConfig } from "pixi-particles";

const emitterConfig: EmitterConfig | OldEmitterConfig = {
  frequency: 1 / 500,
  lifetime: { min: 0.4, max: 1 },
  pos: { x: 0, y: 0 },
  autoUpdate: true,

  alpha: {
    start: 0.1,
    end: 0,
  },
  scale: {
    start: 0.05,
    end: 0.1,
    minimumScaleMultiplier: 1,
  },
  speed: {
    start: 45,
    end: 45,
    minimumSpeedMultiplier: 1,
  },
  startRotation: {
    min: 0,
    max: 360,
  },
  noRotation: false,
  rotationSpeed: {
    min: 0,
    max: 200,
  },

  maxParticles: 500,
  spawnType: "point",
};

export const getEmitterConfig = (x: number, y: number) => ({
  ...emitterConfig,
  pos: { x, y },
});

export const buttonSize = 85
